package com.hbm.item.designator.advanced;
import com.hbm.registry.HbmSounds;import net.minecraft.core.component.DataComponents;import net.minecraft.network.chat.Component;import net.minecraft.sounds.SoundSource;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.component.CustomData;import net.minecraft.world.level.*;
/** Actual ItemDesingatorRange300-block ray; source excludes only the ordinary LaunchPad, not its sibling LargePad. */
public final class RangeDesignatorItem extends CoordinateDesignatorItem{@Override public InteractionResultHolder<ItemStack> use(Level level,Player player,InteractionHand hand){var stack=player.getItemInHand(hand);var from=player.getEyePosition(1);var hit=level.clip(new ClipContext(from,from.add(player.getViewVector(1).scale(300)),ClipContext.Block.OUTLINE,ClipContext.Fluid.NONE,player));var pos=hit.getBlockPos();if(!net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(level.getBlockState(pos).getBlock()).toString().equals("hbm:launch_pad")){CustomData.update(DataComponents.CUSTOM_DATA,stack,tag->{tag.putInt("xCoord",pos.getX());tag.putInt("zCoord",pos.getZ());});if(level.isClientSide)player.displayClientMessage(Component.translatable("item.hbm.designator.range_position_set",pos.getX(),pos.getZ()),false);level.playSound(player,player.getX(),player.getY(),player.getZ(),HbmSounds.get("item.techBleep"),SoundSource.PLAYERS,1,1);}return InteractionResultHolder.sidedSuccess(stack,level.isClientSide);}}
